function declarationsBefore(source: string, marker: string): string {
  const end = source.indexOf(marker)
  if (end < 0) throw new Error(`AI SDK contract boundary missing: ${marker}`)
  return source.slice(0, end)
}

function contractBetween(source: string, start: string, end: string): string {
  const begin = source.indexOf(start)
  const finish = source.indexOf(end, begin)
  if (begin < 0 || finish < begin) throw new Error(`AI SDK contract boundary missing: ${start} / ${end}`)
  return source.slice(begin, finish).trim()
}

