export const DND5E_LOCAL_CONTENT_AI_SDK_GUIDE = `${coreGuide}\n\n${subclassGuide}\n\n${featureGuide}`

export function dnd5eLocalContentAiSdkGuide(targetKind: string, sourceText = '', plan?: Dnd5eLocalContentMechanismPlan): string {
  if (['monster', 'background', 'ability-generation'].includes(targetKind)) return ''
  const registeredOperations = '\n当前 Host 已注册的 mechanic operation 完整白名单（仅 id 与 parameters 中定义的参数可用；没有对应处理器就使用声明式 outcomes/Effect，不得发明 handlerId；core.resolve-only 不可代替伤害、状态或其他实际规则效果）：\n' + JSON.stringify(listDnd5eMechanicOperationHandlersV1())
  if (targetKind !== 'spell') {
    let core = coreGuide
    if (plan) {
      core = core.replace(declarationsBefore(spellMechanicsContracts, 'export function dnd5eSpellCantripScalingTotals'), '')
        .replace(declarationsBefore(spellContracts, 'export interface Dnd5eSpellImportBundle'),
          contractBetween(spellContracts, 'export type Dnd5eSpellbookSchoolId', 'export type Dnd5eSpellbookCastingTimeUnit'))
      if (!plan.needsActivities) core = core.replace(activityContracts, '').replace(declarationsBefore(activityPatterns, 'function checked'), '').replace(declarationsBefore(continuationContracts, 'function turnKey'), '')
      if (!plan.needsAreas) core = core.replace(declarationsBefore(areaContracts, 'export function normalizeDnd5ePersistentAreaTurnLifecycle'), '')
    }
    const nativeRestExample = /长休|短休|long rest|short rest/iu.test(sourceText)
      ? '\n子职原生 Activity 的虚构示例（放入根 activities；同时在 example-school 的 abilities 保留 id:example-gift 的能力、等级和触发元数据，旧 effects 不重复执行；所有数值、目标及限制须按原文调整）：\n'
        + JSON.stringify(DND5E_NATIVE_SUBCLASS_REST_EXAMPLE)
        + '\n原文如果在多个效果中择一，使用同一个 Activity 的 choices/branches，保证该休息窗口只消费一次；不要拆成可各用一次的多个 Activity。此示例只演示护甲，不代表武器、材料制作或所有能力都已覆盖。不要把已支持的物品选择、休息窗口、来源死亡/休息清理重新列为协议缺口。'
      : ''
    return `${core}\n\n${plan ? focusDnd5eSubclassContracts(subclassGuide, plan) : subclassGuide}${['feat', 'feature', 'subclass', 'auto'].includes(targetKind) ? '\n\n' + featureGuide : ''}` + registeredOperations + nativeRestExample
  }
  if (!sourceText) return coreGuide
  // Spell execution is Activity-based. The legacy mechanics implementation is
  // redundant context and previously encouraged non-executable metadata output.
  let guide = coreGuide.replace(declarationsBefore(spellMechanicsContracts, 'export function dnd5eSpellCantripScalingTotals'), '') + registeredOperations
  guide = guide.replace('法术 mechanics 协议（复杂效果优先用 activities；不要在 mechanics 内发明字段）：', '执行配置使用 Activity；不需要填写旧式 mechanics。')
  const ruleBody = sourceText.split('[职业清单参考]')[0]
  if (!/区域|范围|半径|立方|球|锥|墙|地形|area|radius|sphere|cone|wall/iu.test(ruleBody)) {
    guide = guide.replace(declarationsBefore(areaContracts, 'export function normalizeDnd5ePersistentAreaTurnLifecycle'), '')
  }
  return guide + '\n逐项核对目标资格、伤害/治疗、豁免、反应窗口、持续时间、重复触发、次数消耗和结束清理。用上述合法 Activity/Effect 字段组合确定性机制。不能因为存在一项叙事效果，就省略其他可表达的机制；未覆盖的每项原文规则必须写入 unsupported。原文没有升环规则、没有界面说明，不属于未覆盖机制；不要为这些事项生成 unsupported 或 DM 裁定 operation。方向和位置选择使用已有目标模板。Effect 内不可嵌入 runtime triggers；后续活动使用顶层 Activity invocation/triggers 并以活动效果需求限制触发资格。每个 damageType 必须是协议中的单个伤害类型，需要选择时用 choices/branches。full/partial 是覆盖说明，不是可执行活动。禁止生成 authorityBinding：这是 Host 原生绑定，不属于 AI 可写执行配置。'
}






